/* build-wordfreq-lang.mjs: regenerate the bundled French, Spanish, German, Portuguese and Italian
 * word lists (`alcoia/src/libs/wordfreq/common-words-<lang>.js`).
 *
 * Build-time tool only; nothing is fetched when the extension runs. Source: Hermit Dave's
 * FrequencyWords, 2018 lists (words counted over OpenSubtitles). Licence of that content: CC BY-SA 4.0.
 * Attribution and the licence note are in docs/NOTICE.md and in the header of each generated file.
 * The top TOP_N words per language are kept; a word outside the list counts as "less common" in
 * text-difficulty.js. Run: npm run wordfreq:lang
 */
import { writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const OUT = path.resolve(HERE, '..', 'alcoia', 'src', 'libs', 'wordfreq');
const BASE = 'https://raw.githubusercontent.com/hermitdave/FrequencyWords/master/content/2018';
const LANGS = ['fr', 'es', 'de', 'pt', 'it'];
const TOP_N = 5000;

for (const lang of LANGS) {
  const res = await fetch(`${BASE}/${lang}/${lang}_50k.txt`);
  if (!res.ok) throw new Error(`${lang}: HTTP ${res.status}`);
  const words = [];
  for (const line of (await res.text()).split('\n')) {
    const w = line.split(' ')[0].trim().toLowerCase();
    if (!w || !/^\p{L}+$/u.test(w)) continue;
    if (!words.includes(w)) words.push(w);
    if (words.length >= TOP_N) break;
  }
  const header = `/* Generated by tools/build-wordfreq-lang.mjs. Top ${words.length} words for "${lang}" from FrequencyWords (2018, OpenSubtitles) by Hermit Dave, CC BY-SA 4.0 (https://github.com/hermitdave/FrequencyWords). See docs/NOTICE.md. Do not hand-edit. */\n`;
  writeFileSync(path.join(OUT, `common-words-${lang}.js`),
    `${header}export const COMMON_WORDS_${lang.toUpperCase()} = new Set(${JSON.stringify(words)});\n`);
  console.log(lang, words.length);
}
